static struct drm_plane * * sun8i_layers_init ( struct drm_device * drm , struct sunxi_engine * engine ) { struct drm_plane * * planes ; struct sun8i_mixer * mixer = engine_to_sun8i_mixer ( engine ) ; int i ; planes = devm_kcalloc ( drm -> dev , mixer -> cfg -> vi_num + mixer -> cfg -> ui_num + 1 , sizeof ( * planes ) , GFP_KERNEL ) ; for ( i = 0 ; i < mixer -> cfg -> vi_num ; i ++ ) { struct sun8i_vi_layer * layer ; layer = sun8i_vi_layer_init_one ( drm , mixer , i ) ; if ( IS_ERR ( layer ) ) { dev_err ( drm -> dev , "Couldn't initialize overlay plane\n" ) ; return ERR_CAST ( layer ) ; } planes [ i ] = & layer -> plane ; } for ( i = 0 ; i < mixer -> cfg -> ui_num ; i ++ ) { struct sun8i_ui_layer * layer ; layer = sun8i_ui_layer_init_one ( drm , mixer , i ) ; if ( IS_ERR ( layer ) ) { dev_err ( drm -> dev , "Couldn't initialize %s plane\n" , i ?"overlay" : "primary" ) ; return ERR_CAST ( layer ) ; } planes [ mixer -> cfg -> vi_num + i ] = & layer -> plane ; } return planes ; } 